import { Schema, model } from 'mongoose';

export const PRIORITIES = ['low', 'medium', 'high'] as const;
export const COLUMN_IDS = ['todo', 'in_progress', 'done'] as const;

export type Priority = (typeof PRIORITIES)[number];
export type ColumnId = (typeof COLUMN_IDS)[number];

export interface Task {
  _id: string;
  title: string;
  description: string;
  priority: Priority;
  columnId: ColumnId;
  orderIndex: number;
  tags: string[];
  version: number;
  createdAt: Date;
  updatedAt: Date;
}

const taskSchema = new Schema<Task>(
  {
    // A string UUID generated by the client, so a retried create can't make a duplicate.
    _id: { type: String, required: true },
    title: { type: String, required: true, trim: true, minlength: 1, maxlength: 120 },
    description: { type: String, default: '', maxlength: 2000 },
    priority: { type: String, enum: PRIORITIES, default: 'medium' },
    columnId: { type: String, enum: COLUMN_IDS, required: true },
    orderIndex: { type: Number, required: true },
    tags: { type: [String], default: [] },
    version: { type: Number, default: 0 },
  },
  // versionKey: false drops Mongoose's own __v. Our `version` field is the one the
  // API checks, and two version counters would be confusing.
  { timestamps: true, versionKey: false },
);

// Serves "all tasks of a column in order" and the neighbor lookups when moving.
taskSchema.index({ columnId: 1, orderIndex: 1 });

export const TaskModel = model<Task>('Task', taskSchema);
